import java.io.*;import com.jpexs.decompiler.flash.SWF;class InspectHelper{public static void main(String[]args)throws Exception{var s=new SWF(new FileInputStream(args[0]),true);for(var p:s.getAS3Packs())System.out.println(p.getClassPath()+" tag="+s.getTags().indexOf((com.jpexs.decompiler.flash.tags.Tag)p.abc.parentTag)+" instances="+p.abc.instance_info.size()+" scripts="+p.abc.script_info.size()+" scriptIndex="+p.scriptIndex+" traits="+p.abc.script_info.get(p.scriptIndex).traits.traits.size());}}
